edges.supplied_arguments:
Where-Object {
      $candidate = $_
      $title = [string]$candidate.MainWindowTitle
      if ([string]::IsNullOrWhiteSpace($title)) { return $false }
      if ($CRP -and ($title -like "*$CRP*" -or $title -like "*$($CRP.Replace('-', '_'))*")) {
        return $true
      }
      return ($title -like "*$RepositoryName*" -and ($title -like '*<-->*' -or $title -like '*Review*' -or $title -like '*Beyond Compare*'))
    }

ForEach-Object {
        [pscustomobject]@{
          Id = [int]$_.id
          Repository = ConvertTo-WorkspacePushRepositoryName -RepositoryName $_.origin_repo
          BundlePath = Resolve-WorkspaceProposalBundlePath -Proposal $_ -RepositoryName $_.origin_repo
        }
      }

ForEach-Object {
        $props = Get-ItemProperty -Path $_.PSPath -ErrorAction SilentlyContinue
        if ($props.DriverDesc -like "*Intel*" -or $props.DriverDesc -like "*Ethernet*") {
            Write-Host "  --> Disabling WoL/Pattern wake on: $($props.DriverDesc)" -ForegroundColor Green
            Set-ItemProperty -Path $_.PSPath -Name "*WakeOnPattern" -Value "0" -Type String -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path $_.PSPath -Name "*WakeOnMagicPacket" -Value "0" -Type String -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path $_.PSPath -Name "WakeOnMagicPacketFromS5" -Value "0" -Type String -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path $_.PSPath -Name "EnablePME" -Value "0" -Type String -Force -ErrorAction SilentlyContinue
        }
    }

ForEach-Object {
  $phase = $_
  [pscustomobject]@{
    Id = $phase.id
    Name = $phase.name
    Scope = $phase.scope
    Status = $phase.status
    WriteAllowedNow = $false
  }
}

Sort-Object `
                @{ Expression = { if ($_.FullName -match "\\scratch\\|\\links\\") { 1 } else { 0 } }; Ascending = $true }, `
                @{ Expression = { $_.LastWriteTime }; Ascending = $false }

Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public class FinalSystemReloader {
    [DllImport("user32.dll", EntryPoint = "SystemParametersInfo")]
    public static extern bool SystemParametersInfo(uint uiAction, uint uiParam, uint pvParam, uint fWinIni);
}
"@

Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public class EnvBroadcaster {
    [DllImport("user32.dll", SetLastError = true, CharSet = CharSet.Auto)]
    public static extern IntPtr SendMessageTimeout(
        IntPtr hWnd, uint Msg, UIntPtr wParam, string lParam,
        uint fuFlags, uint uTimeout, out UIntPtr lpdwResult);
}
"@

Where-Object {
            $dates = $_.dates
            if ($null -eq $dates) { return $false }
            $hasDate = (Get-ObjProperty $dates $eNorm) -ne '-'
            if (-not $hasDate -and $eNorm -eq 'created') { $hasDate = [bool]$_.timestamp }
            if (-not $hasDate -and $eNorm -eq 'pushed') { $hasDate = [bool]$_.pushed_at }
            return $hasDate
        }

ForEach-Object {
            if ($_ -match '^\s*(?<dos>[A-Z]:)?\s*(?<vol>\\Device\\[^\s]+)\s+(?<fs>\S+)\s*(?<status>\S+)?\s*$') {
                $volumeName = $matches['vol']
                if ($volumeName -match '^\\Device\\(Mailslot|Mup|NamedPipe)(\\|$)') {
                    return
                }

                [PSCustomObject]@{
                    DosName    = $matches['dos']
                    VolumeName = $volumeName
                    FileSystem = $matches['fs']
                    Status     = $matches['status']
                }
            }
        }

ForEach-Object {
        $partition = $_
        $accessPaths = @($partition.AccessPaths | Where-Object { $_ -match '^\\\\\?\\Volume\{[^}]+\}\\$' })

        foreach ($accessPath in $accessPaths) {
            $serial = Get-VolumeSerialHex -Path $accessPath
            if (-not $serial) { continue }

            if (-not $map.ContainsKey($serial)) {
                $map[$serial] = [PSCustomObject]@{
                    PartitionType   = $partition.Type
                    GptType         = $partition.GptType
                    MbrType         = $partition.MbrType
                    DiskNumber      = $partition.DiskNumber
                    PartitionNumber = $partition.PartitionNumber
                    StartOffset     = [int64]$partition.Offset
                    SizeBytes       = $partition.Size
                }
            }
        }
    }
